parameters.jsCode:
const input = $input.first().json;
const clientId = $('Logic: Extract Input Data').first().json.client_id;
const clientUid = $('Logic: Extract Input Data').first().json.client_uid;
const clientName = $('Logic: Extract Input Data').first().json.client_name;
const sheetsId = $('Logic: Extract Input Data').first().json.sheets_id;
const driveFolderId = $('Logic: Extract Input Data').first().json.drive_folder_id;
const telegramId = $('Logic: Extract Input Data').first().json.telegram_id;

// ── Extract raw text from all possible Gemini output shapes ──────────────────
let days;

// Shape 1: simplify=false → candidates array
if (input.candidates?.[0]?.content?.parts?.[0]?.text) {
  const raw = input.candidates[0].content.parts[0].text;
  const cleaned = raw.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();
  try {
    days = JSON.parse(cleaned);
  } catch(e) {
    throw new Error('Parser: JSON.parse failed (Shape 1) — ' + e.message + ' | Raw: ' + raw.slice(0,300));
  }
}
// Shape 2: jsonOutput=true already parsed into array directly
else if (Array.isArray(input)) {
  days = input;
}
// Shape 3: jsonOutput=true parsed, stored under text key as array
else if (Array.isArray(input.text)) {
  days = input.text;
}
// Shape 4: raw string in text field
else if (typeof input.text === 'string') {
  const cleaned = input.text.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();
  try {
    days = JSON.parse(cleaned);
  } catch(e) {
    throw new Error('Parser: JSON.parse failed (Shape 4) — ' + e.message + ' | Raw: ' + input.text.slice(0,300));
  }
}
// Shape 5: message content blocks
else if (input.message?.content) {
  const block = Array.isArray(input.message.content)
    ? input.message.content.find(b => b.type === 'text')
    : null;
  const raw = block ? block.text : JSON.stringify(input.message.content);
  const cleaned = raw.replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```\s*$/,'').trim();
  try {
    days = JSON.parse(cleaned);
  } catch(e) {
    throw new Error('Parser: JSON.parse failed (Shape 5) — ' + e.message);
  }
}
else {
  throw new Error('Parser: Cannot find array in Gemini output. Keys found: ' + JSON.stringify(Object.keys(input)));
}

// ── Validate ─────────────────────────────────────────────────────────────────
if (!Array.isArray(days)) {
  throw new Error('Parser: Expected array, got ' + typeof days);
}
if (days.length !== 30) {
  throw new Error('Parser: Expected 30 items, got ' + days.length);
}

// ── Map to output rows ────────────────────────────────────────────────────────
const today = new Date();

return days.map((day, i) => {
  const postingDate = new Date(today);
  postingDate.setDate(today.getDate() + i);
  const dateStr = postingDate.toISOString().split('T')[0];

  const isCarousel = (day.format || '').toLowerCase() === 'carousel';
  const carouselObj = isCarousel && day.carousel_content ? day.carousel_content : null;

  return {
    json: {
      // ── Identity ────────────────────────────────────────────────────────────
      client_id:        clientId,
      client_uid:       clientUid,
      client_name:      clientName,
      sheets_id:        sheetsId,
      drive_folder_id:  driveFolderId,
      telegram_id:      telegramId,

      // ── Planning fields ─────────────────────────────────────────────────────
      day_number:       day.day_number      ?? (i + 1),
      format:           (day.format         || 'post').toLowerCase(),
      posting_date:     dateStr,
      target_platform:  day.target_platform || '',
      core_topic:       day.core_topic      || '',
      strategic_angle:  day.strategic_angle || '',
      image_prompt:     day.image_prompt    || '',
      keywords:         Array.isArray(day.keywords) ? day.keywords.join(', ') : (day.keywords || ''),
      keyword_to_use:   day.keyword_to_use  || '',
      cta:              day.cta             || '',
      cta_url:          day.cta_url         || '',
      arabic_required:  day.arabic_required === true,
      carousel_content: carouselObj || null,

      // ── Supabase row ────────────────────────────────────────────────────────
      supabase_row: {
        client_id:        clientId,
        day_number:       day.day_number      ?? (i + 1),
        format:           (day.format         || 'post').toLowerCase(),
        posting_date:     dateStr,
        target_platform:  day.target_platform || '',
        core_topic:       day.core_topic      || '',
        strategic_angle:  day.strategic_angle || '',
        image_prompt:     day.image_prompt    || '',
        keywords:         Array.isArray(day.keywords) ? day.keywords.join(', ') : (day.keywords || ''),
        keyword_to_use:   day.keyword_to_use  || '',
        cta:              day.cta             || '',
        cta_url:          day.cta_url         || '',
        arabic_required:  day.arabic_required === true,
        carousel_content: carouselObj         || null,
        status:           'Draft',
        author:           'AI Agent',
        created_at:       new Date().toISOString()
      },

      // ── Sheet row ───────────────────────────────────────────────────────────
      sheet_row: {
        'Day Number':            day.day_number      ?? (i + 1),
        'Format':                (day.format         || 'post').toLowerCase(),
        'Posting Date':          dateStr,
        'Target Platform':       day.target_platform || '',
        'Core Service / Topic':  day.core_topic      || '',
        'Strategic Angle':       day.strategic_angle || '',
        'Image Description':     day.image_prompt    || '',
        'Keyword To Use':        day.keyword_to_use  || '',
        'SEO AEO AIEO Keywords': Array.isArray(day.keywords) ? day.keywords.join(', ') : (day.keywords || ''),
        'CTA':                   day.cta             || '',
        'CTA URL':               day.cta_url         || '',
        'Arabic Required':       day.arabic_required === true ? 'Yes' : 'No',
        'Slide 1':               isCarousel ? (carouselObj?.slide_1 || '') : '',
        'Slide 2':               isCarousel ? (carouselObj?.slide_2 || '') : '',
        'Slide 3':               isCarousel ? (carouselObj?.slide_3 || '') : '',
        'Slide 4':               isCarousel ? (carouselObj?.slide_4 || '') : '',
        'Slide 5':               isCarousel ? (carouselObj?.slide_5 || '') : '',
        'Slide 6':               isCarousel ? (carouselObj?.slide_6 || '') : '',
        'Slide 7':               isCarousel ? (carouselObj?.slide_7 || '') : '',
        'Done By':               'AI Agent',
        'Status':                'Draft',
        'Output Assets':         '',
        'Comment':               '',
        'Post Copy':             '',
        'Hashtags':              '',
        'Live Links':            ''
      }
    }
  };
});

const clientId = $('Logic: Extract Input Data').first().json.client_id;
const sheetsId = $('Logic: Extract Input Data').first().json.sheets_id;
const telegramId = $('Logic: Extract Input Data').first().json.telegram_id;
const clientName = $('Logic: Extract Input Data').first().json.client_name;

const input = $input.first().json;
const rows = Array.isArray(input.all_rows) ? input.all_rows : [input];

let doc = '30-DAY CONTENT CALENDAR\n========================\n\n';
doc += `Client: ${clientName}\n`;
doc += `Generated: ${new Date().toISOString().split('T')[0]}\n\n`;

rows.forEach(row => {
  const day     = row.day_number ?? '?';
  const fmt     = (row.format ?? 'unknown').toUpperCase();
  const date    = row.posting_date ?? '';
  const plat    = row.target_platform ?? '';
  const topic   = row.core_topic ?? '';
  const angle   = row.strategic_angle ?? '';
  const kw      = row.keyword_to_use ?? '';
  const cta     = row.cta ?? '';
  const ctaUrl  = row.cta_url ?? '';
  const arabic  = row.arabic_required ? 'YES' : 'No';
  const imgP    = row.image_prompt ?? '';

  doc += `DAY ${day} — ${fmt} | ${plat}\n`;
  doc += `Date: ${date}\n`;
  doc += `Topic: ${topic}\n`;
  doc += `Strategic Angle: ${angle}\n`;
  doc += `Keyword: ${kw}\n`;
  doc += `CTA: ${cta}\n`;
  doc += `CTA URL: ${ctaUrl}\n`;
  doc += `Arabic Version: ${arabic}\n`;
  doc += `Image Prompt: ${imgP}\n`;

  if (fmt === 'CAROUSEL' && row.carousel_content) {
    let cc = row.carousel_content;
    if (typeof cc === 'string') { try { cc = JSON.parse(cc); } catch(e) {} }
    doc += `Carousel Slides:\n`;
    for (let i = 1; i <= 7; i++) {
      const s = cc[`slide_${i}`];
      if (s) doc += `  Slide ${i}: ${s}\n`;
    }
  }
  doc += '\n---\n\n';
});

return [{ json: { document_text: doc, client_id: clientId, sheets_id: sheetsId, telegram_id: telegramId } }];
